            min_y = min(y for y, x in cells); max_y = max(y for y, x in cells)
            min_x = min(x for y, x in cells); max_x = max(x for y, x in cells)
            height, width = max_y - min_y + 1, max_x - min_x + 1
            if len(cells) != height * width:
                continue
            sides = [
                min_y > 0 and all(grid[min_y - 1][x] != background for x in range(min_x, max_x + 1)),
